 const [loading,setLoading]=useState(false),[connection,setConnection]=useState<boolean|null>(null),[loadError,setLoadError]=useState(''),[range,setRange]=useState('month'),[search,setSearch]=useState(''),[filter,setFilter]=useState('all'),[tab,setTab]=useState('overview'),[reportTab,setReportTab]=useState('profit');
